const registrarLoteDeRenglones = `-- name: RegistrarLoteDeRenglones :one
insert into order_line_batches (client_uuid, order_id)
values ($1, $2)
on conflict do nothing
returning order_id
`

type RegistrarLoteDeRenglonesParams struct {
	ClientUuid uuid.UUID `json:"client_uuid"`
	OrderID    int64     `json:"order_id"`
}

// Marca que este lote de renglones ya se aplicó. Devuelve la fila SOLO si la insertó.
//
// `on conflict do nothing` + `returning`: cero filas significa "esta llave ya estaba", que es la
// señal de reintento. Se hace con un insert y no con un select previo porque el insert es atómico —
// un select y luego un insert dejan la ventana entre los dos, y esa ventana es exactamente el doble
// tap que esto viene a cerrar.
//
// company_id lo auto-sella el default (GUC del tenant).
func (q *Queries) RegistrarLoteDeRenglones(ctx context.Context, arg RegistrarLoteDeRenglonesParams) (int64, error) {
	row := q.db.QueryRow(ctx, registrarLoteDeRenglones, arg.ClientUuid, arg.OrderID)
	var order_id int64
	err := row.Scan(&order_id)
	return order_id, err
}

const restockCancelledLine = `-- name: RestockCancelledLine :exec
insert into stock_movements (item_type, ingredient_id, product_id, movement_type, quantity, order_id, order_line_id, user_id, reason,
                             modifier_option_id, component_of_product_id)
select sm.item_type, sm.ingredient_id, sm.product_id, 'cancelacion', -sm.quantity, sm.order_id, sm.order_line_id,
       $1, 'cancelación de renglón', sm.modifier_option_id, sm.component_of_product_id
from stock_movements sm
where sm.order_line_id = $2 and sm.movement_type = 'venta'
`

type RestockCancelledLineParams struct {
	ActorID *int64 `json:"actor_id"`
	LineID  *int64 `json:"line_id"`
}

// Repone el insumo de UN renglón, revirtiendo los movimientos que de verdad salieron por él.
//
// Revierte lo registrado y no un recálculo con la receta de HOY: una receta que cambió entre la
// venta y la cancelación repondría una cantidad distinta de la que se descontó.
//
// Un renglón anterior a la migración 0060 no tiene movimientos ligados y no repone nada. Es la
// decisión: de un movimiento viejo no consta a qué renglón pertenecía, y adivinarlo inventaría
// existencias.
func (q *Queries) RestockCancelledLine(ctx context.Context, arg RestockCancelledLineParams) error {
	_, err := q.db.Exec(ctx, restockCancelledLine, arg.ActorID, arg.LineID)
	return err
}

const restockCancelledOrder = `-- name: RestockCancelledOrder :exec
insert into stock_movements (item_type, ingredient_id, product_id, movement_type, quantity, order_id, order_line_id, user_id, reason,
                             modifier_option_id, component_of_product_id)
select sm.item_type, sm.ingredient_id, sm.product_id, 'cancelacion', -sum(sm.quantity), sm.order_id, sm.order_line_id,
       $1, 'cancelación de orden', sm.modifier_option_id, sm.component_of_product_id
from stock_movements sm
left join order_lines ol on ol.id = sm.order_line_id
where sm.order_id = $2 and sm.movement_type in ('venta', 'cancelacion')
  and ol.cancelled_at is null
group by sm.item_type, sm.ingredient_id, sm.product_id, sm.order_id, sm.order_line_id,
         sm.modifier_option_id, sm.component_of_product_id
having sum(sm.quantity) <> 0
`

type RestockCancelledOrderParams struct {
	ActorID *int64 `json:"actor_id"`
	Oid     *int64 `json:"oid"`
}

// Repone el stock de una orden cancelada: lo NETO de cada renglón, venta menos lo ya repuesto.
//
// Antes invertía todas las ventas del pedido, y lo que ya se había repuesto al cancelar un renglón
// volvía a entrar: un sobrante falso en el almacén por cada renglón cancelado antes del pedido. Se
// agrupa también por renglón para que la reposición quede ligada a él, igual que la de un renglón.
//
// Se salta además los renglones YA QUITADOS: quitar el renglón ya decidió su inventario, y el que se
// quitó ya consumido (enviado a cocina) no tiene nada que volver aunque su neto no sea cero. Los
// movimientos sin renglón (anteriores a 0060) siguen entrando: de ellos no consta de qué renglón
// salieron.
func (q *Queries) RestockCancelledOrder(ctx context.Context, arg RestockCancelledOrderParams) error {
	_, err := q.db.Exec(ctx, restockCancelledOrder, arg.ActorID, arg.Oid)
	return err
}

