const splitOffOrderLine = `-- name: SplitOffOrderLine :one
insert into order_lines (order_id, product_id, product_name, quantity, unit_price, modifiers_total,
                         unit_cost, line_total, notes, delivered_qty, enviado_a_cocina_at)
select $1, ol.product_id, ol.product_name, $2, ol.unit_price, ol.modifiers_total,
       ol.unit_cost, $3, ol.notes, $4, ol.enviado_a_cocina_at
from order_lines ol
where ol.id = $5
returning id
`

type SplitOffOrderLineParams struct {
	OrderID      int64           `json:"order_id"`
	Quantity     decimal.Decimal `json:"quantity"`
	LineTotal    decimal.Decimal `json:"line_total"`
	DeliveredQty decimal.Decimal `json:"delivered_qty"`
	LineID       int64           `json:"line_id"`
}

// Parte un renglón: crea uno nuevo con `quantity` piezas que copia precio, modificadores por
// unidad, costo, nota y estado de cocina del original. `order_id` puede ser otro pedido (pasar
// productos). `parent_line_id` no se copia: nadie lo escribe y partir no arrastra hijos.
func (q *Queries) SplitOffOrderLine(ctx context.Context, arg SplitOffOrderLineParams) (int64, error) {
	row := q.db.QueryRow(ctx, splitOffOrderLine,
		arg.OrderID,
		arg.Quantity,
		arg.LineTotal,
		arg.DeliveredQty,
		arg.LineID,
	)
	var id int64
	err := row.Scan(&id)
	return id, err
}

const sumOrderPayments = `-- name: SumOrderPayments :one
select coalesce(sum(amount), 0)::numeric(10,2) as pagado,
       coalesce(sum(tip_amount), 0)::numeric(10,2) as propina
from order_payments where order_id = $1
`

type SumOrderPaymentsRow struct {
	Pagado  decimal.Decimal `json:"pagado"`
	Propina decimal.Decimal `json:"propina"`
}

// Lo ya cobrado de un pedido, y la propina ya registrada. Se lee dentro de la tx del cobro y con el
// pedido bloqueado, que es lo que impide que dos cajeros cobrando a la vez registren cada uno el
// total completo.
//
// La propina viaja en la misma pasada porque su tope es ACUMULADO: se topa cada cobro por separado
// y tres pagos de $250 de propina sobre una cuenta de $250 pasan los tres, con el cajón esperando
// $750 que nadie dejó.
func (q *Queries) SumOrderPayments(ctx context.Context, orderID int64) (SumOrderPaymentsRow, error) {
	row := q.db.QueryRow(ctx, sumOrderPayments, orderID)
	var i SumOrderPaymentsRow
	err := row.Scan(&i.Pagado, &i.Propina)
	return i, err
}

const sumOrderPaymentsByMethod = `-- name: SumOrderPaymentsByMethod :many
select pm.id as method_id, pm.name, pm.affects_cash_drawer as toca_el_cajon, pm.is_active,
       coalesce(sum(op.amount), 0)::numeric(10,2) as cobrado
from order_payments op
join payment_methods pm on pm.id = op.payment_method_id
where op.order_id = $1
group by pm.id, pm.name, pm.affects_cash_drawer, pm.is_active
order by min(op.created_at)
`

type SumOrderPaymentsByMethodRow struct {
	MethodID    int16           `json:"method_id"`
	Name        string          `json:"name"`
	TocaElCajon bool            `json:"toca_el_cajon"`
	IsActive    bool            `json:"is_active"`
	Cobrado     decimal.Decimal `json:"cobrado"`
}

// Cuánto entró por CADA medio de pago en un pedido, en el orden en que entró.
//
// Es lo que decide de dónde sale cada peso al devolver: el dinero sale por donde entró. Devolver en
// efectivo lo que entró por tarjeta saca del cajón dinero que nunca estuvo ahí, y el arqueo cierra
// con un faltante inventado.
//
// `is_active` viaja pero NO filtra: por un método desactivado ya no debe ENTRAR dinero, pero el que
// entró tiene que poder salir por donde entró, o queda atrapado.
//
// QUIÉN SALE DEL CAJÓN ES `affects_cash_drawer`, NO `kind = 'efectivo'` (spec 015, FR-018).
// «Didi efectivo» es de tipo plataforma y su dinero entra al cajón cuando lo reparte gente del
// local: son billetes en el mismo montón. Decidirlo por el tipo devolvía $135 de billetes sin
// registrar la salida, y el corte cerraba con un faltante de $135 que nadie podía explicar.
func (q *Queries) SumOrderPaymentsByMethod(ctx context.Context, orderID int64) ([]SumOrderPaymentsByMethodRow, error) {
	rows, err := q.db.Query(ctx, sumOrderPaymentsByMethod, orderID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []SumOrderPaymentsByMethodRow{}
	for rows.Next() {
		var i SumOrderPaymentsByMethodRow
		if err := rows.Scan(
			&i.MethodID,
			&i.Name,
			&i.TocaElCajon,
			&i.IsActive,
			&i.Cobrado,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const sumOrderRefunds = `-- name: SumOrderRefunds :one
select coalesce(sum(amount), 0)::numeric(10,2) as devuelto_total,
       coalesce(sum(amount) filter (where order_line_id = $1), 0)::numeric(10,2) as devuelto_del_renglon
from order_refunds where order_id = $2
`

type SumOrderRefundsParams struct {
	LineID  *int64 `json:"line_id"`
	OrderID int64  `json:"order_id"`
}

type SumOrderRefundsRow struct {
	DevueltoTotal      decimal.Decimal `json:"devuelto_total"`
	DevueltoDelRenglon decimal.Decimal `json:"devuelto_del_renglon"`
}

// Lo ya devuelto de un pedido, y de UNO de sus renglones.
//
// Las dos cifras en una pasada porque el tope de un renglón es lo cobrado de ESE renglón: sin esa
// cota, devolver tres veces un platillo de $60 en un pedido de $500 pasa sin que nada lo frene.
func (q *Queries) SumOrderRefunds(ctx context.Context, arg SumOrderRefundsParams) (SumOrderRefundsRow, error) {
	row := q.db.QueryRow(ctx, sumOrderRefunds, arg.LineID, arg.OrderID)
	var i SumOrderRefundsRow
	err := row.Scan(&i.DevueltoTotal, &i.DevueltoDelRenglon)
	return i, err
}
